  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Welcome Back: Present Tense and Question Review$j$, $j${"readings": [{"title": "Proverbs 1 (King James Version)", "url": "/portal/bible/Proverbs/1"}], "body": "Proverbs 1:5 says, A wise man will hear, and will increase learning. Spanish 2 builds on what you already know, so we begin by reviewing the present tense. Regular verbs follow patterns. For ar verbs the endings are o, as, a, amos and an, so hablar becomes hablo, hablas, habla, hablamos, hablan. For er verbs the endings are o, es, e, emos and en, so comer becomes como, comes, come, comemos, comen. For ir verbs the endings are o, es, e, imos and en, so vivir becomes vivo, vives, vive, vivimos, viven.\n\nThree verbs you must know by heart are ser, estar and tener. Ser is soy, eres, es, somos, son and tells who or what someone is. Estar is estoy, estás, está, estamos, están and tells where someone is and how they feel. Tener is tengo, tienes, tiene, tenemos, tienen and also tells age, as in Tengo dieciséis años.\n\nQuestion words are qué, quién, dónde, cuándo, por qué, cómo, cuánto and cuál. Each has an accent mark, and each question begins with ¿ and ends with ?. Worked example: ¿Dónde vives? Vivo en Pompano Beach. ¿Cuándo estudias? Estudio por la tarde. Common mistake: leaving out the accent on question words, which changes the meaning of por qué (why) and porque (because).\n\nYour task: (1) Conjugate trabajar, aprender and escribir. (2) Write six questions with six different question words and answer each in Spanish.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back to Spanish 2. Listen, Proverbs 1:5 says a wise man will hear, and will increase learning. We begin with a review.\n\nNow watch this. Ar verbs take o, as, a, amos, an. Hablo, hablas, habla, hablamos, hablan. Er verbs take o, es, e, emos, en. Ir verbs take o, es, e, imos, en.\n\nRemember ser, estar and tener. Soy, estoy, tengo. Ser tells who you are, estar tells where you are and how you feel, and tener tells your age.\n\nQuestion words carry accents: qué, quién, dónde, cuándo, por qué, cómo, cuánto, cuál. Do not confuse por qué with porque.\n\nYour task is to conjugate three verbs and write six questions with answers. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Welcome Back: Present Tense and Question Review$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Reflexive Verbs and the Daily Routine$j$, $j${"readings": [{"title": "Psalm 5 (King James Version)", "url": "/portal/bible/Psalms/5"}], "body": "Psalm 5:3 says, My voice shalt thou hear in the morning, O LORD; in the morning will I direct my prayer unto thee, and will look up. A morning routine is a good place to practice reflexive verbs. A reflexive verb describes an action that a person does to himself. The infinitive ends in se, as in levantarse, to get up.\n\nUse a reflexive pronoun before the conjugated verb: me, te, se, nos, se. Levantarse becomes me levanto, te levantas, se levanta, nos levantamos, se levantan. Other useful verbs are despertarse (to wake up), ducharse (to shower), lavarse (to wash oneself), cepillarse los dientes (to brush one's teeth), peinarse (to comb one's hair), vestirse (to get dressed) and acostarse (to go to bed).\n\nSome are stem changing. Despertarse changes e to ie: me despierto. Vestirse changes e to i: me visto. Acostarse changes o to ue: me acuesto.\n\nWorked example: Me despierto a las seis, me ducho, me visto y oro antes de desayunar. Con un infinitivo, the pronoun may go before the verb or attach to the infinitive: Voy a acostarme or Me voy a acostar. Common mistake: using the English pattern, I wash my hands, with mi. In Spanish say Me lavo las manos, using the article las.\n\nYour task: (1) Write the full present tense of lavarse. (2) Describe your morning in six Spanish sentences.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Psalm 5:3 says, My voice shalt thou hear in the morning, O LORD. Let us talk about the morning routine.\n\nNow watch this. A reflexive verb ends in se. The pronouns are me, te, se, nos, se. Me levanto, te levantas, se levanta, nos levantamos, se levantan.\n\nUseful verbs are despertarse, ducharse, lavarse, vestirse and acostarse. Some change their stems. Me despierto, me visto, me acuesto.\n\nSay it this way: Me lavo las manos. Do not say mi manos. Spanish uses the article with body parts and clothing.\n\nWith an infinitive you may say Voy a acostarme or Me voy a acostar.\n\nYour task is to conjugate lavarse and describe your morning in six sentences. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Reflexive Verbs and the Daily Routine$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Verbs with Irregular Yo Forms$j$, $j${"readings": [{"title": "Joshua 24 (King James Version)", "url": "/portal/bible/Joshua/24"}], "body": "Joshua 24:15 says, As for me and my house, we will serve the LORD. In Spanish, many common verbs are regular in every form except yo. These verbs have a special yo ending, and learning them lets you say what you do.\n\nThe yo go verbs add a g: hacer becomes hago, poner becomes pongo, salir becomes salgo, traer becomes traigo, oír becomes oigo, tener becomes tengo, venir becomes vengo and decir becomes digo. Other forms of these verbs follow the regular pattern, so hacer is hago, haces, hace, hacemos, hacen, and salir is salgo, sales, sale, salimos, salen.\n\nOther irregular yo forms are saber, sé; ver, veo; dar, doy; conocer, conozco; and traducir, traduzco.\n\nWorked example: Hago la tarea por la noche. Salgo de la iglesia a las doce. Pongo la Biblia en la mesa. Veo a mis amigos los domingos. Common mistake: applying the yo irregular form to every person. Only yo changes, so say tú haces, not tú hagas.\n\nYour task: (1) Conjugate hacer and salir in the present tense. (2) Write six sentences about your week using hago, salgo, pongo, traigo, veo and doy.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, Joshua 24:15 says, As for me and my house, we will serve the LORD. Today we talk about me, the yo form.\n\nNow watch this. Many verbs are regular except in yo. Hacer is hago. Poner is pongo. Salir is salgo. Traer is traigo. Oír is oigo. Tener is tengo. Venir is vengo. Decir is digo.\n\nOther irregular yo forms are sé, veo, doy, conozco and traduzco.\n\nThe rest of the forms are regular. Tú haces, él hace, nosotros hacemos. Only yo changes.\n\nPractice: Hago la tarea. Salgo de la iglesia. Pongo la Biblia en la mesa.\n\nYour task is to conjugate hacer and salir and write six sentences. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Verbs with Irregular Yo Forms$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Saber, Conocer and the Personal A$j$, $j${"readings": [{"title": "John 17 (King James Version)", "url": "/portal/bible/John/17"}], "body": "John 17:3 says, And this is life eternal, that they might know thee the only true God, and Jesus Christ, whom thou hast sent. English has one word, know, but Spanish has two: saber and conocer.\n\nSaber is sé, sabes, sabe, sabemos, saben. Use it for facts, information and learned skills. Sé la respuesta means I know the answer. Sé cantar means I know how to sing. Conocer is conozco, conoces, conoce, conocemos, conocen. Use it to be familiar or acquainted with people, places and things. Conozco a María means I know María. Conozco Miami means I am familiar with Miami.\n\nNotice the little word a in Conozco a María. This is the personal a, which goes before a direct object that is a specific person. Veo a mi abuela means I see my grandmother. For things, no a is needed: Veo la iglesia. Use a before alguien and nadie too: No veo a nadie.\n\nWorked example: ¿Sabes dónde está la biblioteca? ¿Conoces a mi pastor? Common mistake: using conocer for facts. Say Sé que la iglesia abre a las nueve, not Conozco que.\n\nYour task: (1) Write three sentences with saber and three with conocer. (2) Add the personal a where it is needed: Veo ___ mi tío. Visito ___ el museo.\n\nFlorida standards: Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida World Languages standards, Level 2 (WL.K12.NH, WL.K12.IL)", "script": "Welcome back. Listen, John 17:3 says, This is life eternal, that they might know thee the only true God. English has one word for know. Spanish has two.\n\nNow watch this. Saber is for facts and skills. Sé la respuesta. Sé cantar. Conocer is for people and places. Conozco a María. Conozco Miami.\n\nThe forms are sé, sabes, sabe, sabemos, saben, and conozco, conoces, conoce, conocemos, conocen.\n\nNow the personal a. Put a before a specific person who receives the action. Veo a mi abuela. For things, no a. Veo la iglesia.\n\nYour task is to write sentences with saber and conocer and add the personal a. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Saber, Conocer and the Personal A$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Daily Life, Reflexive Verbs and Irregular Verbs$j$, $j${"prompt": "Write a report of at least 300 words in English with Spanish examples. Use complete sentences and label each part. Proverbs 1:5 says, A wise man will hear, and will increase learning.\n\nPart 1: Review the present tense. Conjugate one regular ar, er and ir verb, and write sentences with ser, estar and tener.\nPart 2: Write eight Spanish sentences about your morning and evening routine using at least five reflexive verbs, including two stem changing ones.\nPart 3: List the yo go verbs and five other irregular yo forms, and write six sentences using them.\nPart 4: Explain the difference between saber and conocer, give two examples of each, and explain the personal a.\nPart 5: Write a Spanish dialogue of at least eight lines in which two people ask about each other's day.\nPart 6: Explain how Psalm 5:3 and John 17:3 can shape how you start your day and how you know God.", "rubric": "100 points. Part 1: 15 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 15 points. Part 6: 5 points. Conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Daily Life, Reflexive Verbs and Irregular Verbs$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Morning by Morning$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes your morning routine in English and in at least three Spanish sentences, (2) explains one habit that helps you start the day well, such as prayer, and (3) connects your answer to Psalm 5:3. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can knowing a person in Spanish, using conocer, change the way we welcome neighbors?"}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Morning by Morning$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Welcome Back: Present Tense and Question Review$j$, $j${"questions": [{"q": "The nosotros form of comer is:", "options": ["Comimos", "Comamos", "Comemos", "Comen"]}, {"q": "To tell where someone is, use:", "options": ["Hacer", "Ser", "Estar", "Tener"]}, {"q": "Por qué means:", "options": ["Because", "Why", "Who", "When"]}, {"q": "Tengo dieciséis años means:", "options": ["I was sixteen", "I have sixteen books", "I am sixteen years old", "I want sixteen years"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Welcome Back: Present Tense and Question Review$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,1,2}'::int[], array[$j$Er verbs take emos in the nosotros form.$j$,$j$Estar tells location.$j$,$j$Por qué is a question word that means why.$j$,$j$Spanish uses tener for age.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Welcome Back: Present Tense and Question Review$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Reflexive Verbs and the Daily Routine$j$, $j${"questions": [{"q": "Me levanto means:", "options": ["I am tall", "I wash", "I get up", "I lift"]}, {"q": "The reflexive pronoun for nosotros is:", "options": ["Nos", "Me", "Te", "Se"]}, {"q": "Which is correct?", "options": ["Me lavo mis manos", "Lavo me las manos", "Me lavo las manos", "Me lava las manos"]}, {"q": "Acostarse changes its stem from:", "options": ["o to ue", "a to ue", "e to i", "e to ie"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Reflexive Verbs and the Daily Routine$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,2,0}'::int[], array[$j$Levantarse means to get up.$j$,$j$Nos goes with nosotros.$j$,$j$Spanish uses the article with body parts.$j$,$j$Acostarse is me acuesto.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Reflexive Verbs and the Daily Routine$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Verbs with Irregular Yo Forms$j$, $j${"questions": [{"q": "The yo form of hacer is:", "options": ["Hacio", "Hago", "Hace", "Hazo"]}, {"q": "Salgo means:", "options": ["I leave", "I am", "I give", "I jump"]}, {"q": "The tú form of poner is:", "options": ["Pongo", "Pones", "Pone", "Pongas"]}, {"q": "The yo form of dar is:", "options": ["Da", "Dao", "Do", "Doy"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Verbs with Irregular Yo Forms$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,3}'::int[], array[$j$Hacer is hago in the yo form.$j$,$j$Salgo is the yo form of salir.$j$,$j$Only the yo form is irregular.$j$,$j$Dar is doy.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Verbs with Irregular Yo Forms$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Saber, Conocer and the Personal A$j$, $j${"questions": [{"q": "To say you know a fact, use:", "options": ["Ser", "Saber", "Estar", "Conocer"]}, {"q": "Conozco a María requires the a because María is:", "options": ["A person", "A place", "A fact", "A day"]}, {"q": "Sé cantar means:", "options": ["I know the singer", "I know how to sing", "I sing the song", "I was singing"]}, {"q": "Which is correct?", "options": ["Sabo Miami", "Conozco a Miami", "Conozco Miami", "Sé Miami"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Saber, Conocer and the Personal A$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,2}'::int[], array[$j$Saber is for facts and skills.$j$,$j$The personal a goes before a specific person.$j$,$j$Saber plus an infinitive means to know how.$j$,$j$Conocer is used for places, with no a.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Saber, Conocer and the Personal A$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Daily Life, Reflexive Verbs and Irregular Verbs$j$, $j${"questions": [{"q": "The yo form of salir is:", "options": ["Sale", "Salí", "Salo", "Salgo"]}, {"q": "Me visto means:", "options": ["I see", "I wear nothing", "I live", "I get dressed"]}, {"q": "Ellos viven is the present tense of:", "options": ["Vivir", "Ver", "Venir", "Vender"]}, {"q": "Sé la respuesta uses saber because:", "options": ["It is a person", "It is a place", "It is a fact", "It is a time"]}, {"q": "Which sentence needs the personal a?", "options": ["Veo ___ mi hermano", "Veo ___ la mesa", "Leo ___ la Biblia", "Tengo ___ un libro"]}, {"q": "Nos acostamos means:", "options": ["We wake up", "We go to bed", "We sit", "We wash"]}, {"q": "The tú form of hacer is:", "options": ["Haces", "Hagas", "Hago", "Hacen"]}, {"q": "Question words need:", "options": ["A capital letter", "No special mark", "A hyphen", "An accent mark"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Daily Life, Reflexive Verbs and Irregular Verbs$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,0,2,0,1,0,3}'::int[], array[$j$Salir is salgo.$j$,$j$Vestirse changes e to i.$j$,$j$Viven comes from vivir.$j$,$j$Saber is for facts.$j$,$j$A goes before a specific person.$j$,$j$Acostarse is to go to bed.$j$,$j$Only yo is irregular in hacer.$j$,$j$Qué, dónde and cómo carry accents.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Daily Life, Reflexive Verbs and Irregular Verbs$j$ on conflict (item_id) do nothing;
